v":"HS"},{"t":"[Boys] 20–25 min Easy + 3 strides","lv":"HS"}],"Mid Distance":[{"t":"[Girls] Rest or B1 Easy run (reduced): 10–15 min Easy","lv":"HS"},{"t":"[Boys] B1 Easy run (reduced): 10–15 min Easy + 3 short strides","lv":"HS"}]},"gfocus":{"Mid Distance":"Easy"}},{"day":"Thu","focus":{"HS":"Boys regional"},"all":[],"groups":{"Distance":[{"t":"[Girls] 25–30 min Easy","lv":"HS"},{"t":"[Boys] IHSAA Regional","lv":"HS"}],"Mid Distance":[{"t":"[Girls] B1 Easy run (reduced): 10–15 min Easy","lv":"HS"},{"t":"[Boys] IHSAA Regional","lv":"HS"}]}},{"day":"Fri","focus":{"HS":"Easy"},"all":[],"groups":{"Distance":[{"t":"[Girls] 25 min Easy","lv":"HS"},{"t":"[Boys] Rest or 20 min recovery run","lv":"HS"}],"Mid Distance":[{"t":"[Girls] A3 Speed maintenance (short): 2 × 30m accelerations + 2 × flying 20m, full recovery","lv":"HS"},{"t":"[Boys] Rest","lv":"HS"}]},"gfocus":{"Mid Distance":"Speed"}},{"day":"Sat","focus":{"HS":"Easy"},"all":[],"groups":{"Distance":[{"t":"[Girls] 40–50 min Easy","lv":"HS"},{"t":"[Boys] 35–45 min Easy","lv":"HS"}],"Mid Distance":[{"t":"B1 Easy run (reduced): 10–15 min Easy","lv":"HS"}]},"gfocus":{"Mid Distance":"Easy"}},{"day":"Sun","focus":{"HS":"Rest"},"all":[],"groups":{"Distance":[{"t":"Rest","lv":"HS"}],"Mid Distance":[{"t":"Rest","lv":"HS"}]},"gfocus":{"Mid Distance":"Rest"}}]},{"start":"2027-05-31","days":[{"day":"Mon","focus":{"HS":"Easy"},"all":[],"groups":{"Distance":[{"t":"State week. Fresh legs: no hard intervals, no strength that makes you sore, no fitness tests.","lv":"HS"},{"t":"State dates to be confirmed. The last 48 hours get tailored to your event order.","lv":"HS"},{"t":"30–35 min Easy + 4 relaxed strides","lv":"HS"}],"Mid Distance":[{"t":"State qualifiers only. Taper: speed and rhythm, no fatigue.","lv":"HS"},{"t":"B1 Easy run (reduced): 10–15 min Easy","lv":"HS"},{"t":"4 × 80m relaxed strides","lv":"HS"}]},"gfocus":{"Mid Distance":"Easy"}},{"day":"Tue","focus":{"HS":"Sharpen"},"all":[],"groups":{"Distance":[{"t":"Warm-up and cool-down: 10–15 min Easy each.","lv":"HS"},{"t":"[Hybrid] 2 × 200m at 800 pace, 5 min recovery, then 2 × 80m at Rep pace (relaxed)","lv":"HS"},{"t":"[Distance] 2 × 200m at 1600 pace, 5 min recovery, then 2 × 80m at Rep pace (relaxed)","lv":"HS"}],"Mid Distance":[{"t":"Warm-up: 10 min Easy + dynamic drills. Cool-down: 5–10 min Easy.","lv":"HS"},{"t":"A3 Speed maintenance (short): 2 × 30m accelerations + 2 × flying 20m, full recovery","lv":"HS"},{"t":"2 × 150m relaxed fast, full recovery","lv":"HS"}]},"gfocus":{"Mid Distance":"Sharpen"}},{"day":"Wed","focus":{"HS":"Easy"},"all":[],"groups":{"Distance":[{"t":"20–30 min Easy","lv":"HS"}],"Mid Distance":[{"t":"B1 Easy run (reduced): 10–15 min Easy","lv":"HS"}]},"gfocus":{"Mid Distance":"Easy"}},{"day":"Thu","focus":{"HS":"Easy"},"all":[],"groups":{"Distance":[{"t":"15–25 min Easy + 3 short relaxed strides (adjust for travel)","lv":"HS"}],"Mid Distance":[{"t":"10–15 min Easy + 3 short strides (adjust for travel)","lv":"HS"}]},"gfocus":{"Mid Distance":"Pre-meet"}},{"day":"Fri","focus":{"HS":"Girls state (TBC)"},"all":[],"groups":{"Distance":[{"t":"[Girls] State championship (confirm official date)","lv":"HS"}],"Mid Distance":[{"t":"[Girls] State championship (confirm date)","lv":"HS"}]}},{"day":"Sat","focus":{"HS":"Boys state (TBC)"},"all":[],"groups":{"Distance":[{"t":"[Boys] State championship (confirm official date)","lv":"HS"}],"Mid Distance":[{"t":"[Boys] State championship (confirm date)","lv":"HS"}]}},{"day":"Sun","focus":{"HS":"Rest"},"all":[],"groups":{"Distance":[{"t":"Rest","lv":"HS"}],"Mid Distance":[{"t":"Rest","lv":"HS"}]},"gfocus":{"Mid Distance":"Rest"}}]}]$plan$::jsonb;
  cur jsonb; w jsonb; d jsonb; wk jsonb; days jsonb; dd jsonb; keep jsonb; g text; grp jsonb;
  fw int; fd int;
begin
  select value into cur from public.hub_data where key = 'workouts' for update;
  if cur is null or jsonb_typeof(cur) <> 'array' then cur := '[]'::jsonb; end if;

  for w in select * from jsonb_array_elements(plan) loop
    fw := null;
    for i in 0 .. jsonb_array_length(cur) - 1 loop
      if cur -> i ->> 'start' = w ->> 'start' then fw := i; end if;
    end loop;
    if fw is null then cur := cur || jsonb_build_array(w); continue; end if;

    wk := cur -> fw;
    days := coalesce(wk -> 'days', '[]'::jsonb);
    for d in select * from jsonb_array_elements(w -> 'days') loop
      fd := null;
      for j in 0 .. jsonb_array_length(days) - 1 loop
        if days -> j ->> 'day' = d ->> 'day' then fd := j; end if;
      end loop;
      if fd is null then days := days || jsonb_build_array(d); continue; end if;

      dd := days -> fd;
      if dd -> 'groups' is null or jsonb_typeof(dd -> 'groups') <> 'object' then dd := jsonb_set(dd, '{groups}', '{}'::jsonb); end if;
      for g, grp in select * from jsonb_each(d -> 'groups') loop
        select coalesce(jsonb_agg(x), '[]'::jsonb) into keep
          from jsonb_array_elements(coalesce(dd -> 'groups' -> g, '[]'::jsonb)) x
          where coalesce(x ->> 'lv', '') <> 'HS';
        dd := jsonb_set(dd, array['groups', g], keep || grp);
      end loop;
      if d ? 'gfocus' then
        dd := jsonb_set(dd, '{gfocus}', coalesce(dd -> 'gfocus', '{}'::jsonb) || (d -> 'gfocus'));
      end if;
      if dd -> 'focus' is null or dd ->> 'focus' = '' then
        dd := jsonb_set(dd, '{focus}', d -> 'focus');
      elsif jsonb_typeof(dd -> 'focus') = 'object' and coalesce(dd -> 'focus' ->> 'HS', '') = '' then
        dd := jsonb_set(dd, '{focus,HS}', d -> 'focus' -> 'HS');
      end if;
      if dd -> 'all' is null then dd := dd || '{"all":[]}'::jsonb; end if;
      days := jsonb_set(days, array[fd::text], dd);
    end loop;

    select jsonb_agg(x order by array_position(array['Mon','Tue','Wed','Thu','Fri','Sat','Sun'], x ->> 'day'))
      into days from jsonb_array_elements(days) x;
    cur := jsonb_set(cur, array[fw::text], jsonb_set(wk, '{days}', days));
  end loop;

  insert into public.hub_data (key, value, updated_at) values ('workouts', cur, now())
  on conflict (key) do update set value = excluded.value, updated_at = now();
  raise notice 'Done: % weeks posted in total', jsonb_array_length(cur);
end
$do$;

-- Coach Notes on the Mid-Distance page (key 'midnotes') are readable by signed-in coaches only.
-- Everything else in the hub stays public to read, same as before.
drop policy if exists "Anyone can read the hub" on public.hub_data;
create policy "Anyone can read the hub" on public.hub_data for select
  using (key <> 'midnotes' or public.is_coach());
